#ifndef OPENGL_H
#define OPENGL_H

// Portable OpenGL header. SDL ships an up to date copy of glext.h which
// provides the function pointer typedefs needed by the OpenGL backend; all
// post-1.1 entry points are loaded at runtime through SDL_GL_GetProcAddress.
#include <SDL_opengl.h>

#endif /* OPENGL_H */
